#!/usr/bin/env node

/**
 * ULS Official Component Demo Page Generator
 * 
 * Creates demo pages for official ULS components (from uls-components/src/components/) in the demo app.
 * This is for internal ULS development to showcase official ULS components.
 * 
 * For custom-components (user-created), use: npm run create-custom-component-demo
 * 
 * Usage:
 *   npm run create-uls-component-demo UserCard
 *   node scripts/create-uls-component-demo.mjs UserCard
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';
import readline from 'readline';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const require = createRequire(import.meta.url);

// Helper to get inquirer (lazy load)
async function getInquirer() {
    try {
        // Try CommonJS require first (works better in Node.js)
        const mod = require('inquirer');
        return mod.default || mod;
    } catch (requireErr) {
        try {
            // Fallback to ES module import
            const mod = await import('inquirer');
            return mod.default || mod;
        } catch (importErr) {
            return null;
        }
    }
}

// Fallback prompt using readline
async function promptUsingReadline(defaultCategory, defaultSubCategory) {
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });

    const question = (promptText) => new Promise((resolve) => {
        rl.question(promptText, (answer) => resolve(answer.trim()));
    });

    const ask = async (label, defaultValue) => {
        const suffix = defaultValue ? ` (${defaultValue})` : '';
        const response = await question(`\n${label}${suffix}: `);
        return response || defaultValue;
    };

    try {
        console.log('\n📝 Please provide the following information:');
        const category = await ask('Category', defaultCategory);
        const subCategory = await ask('Sub Category', defaultSubCategory);
        return { category, subCategory };
    } finally {
        rl.close();
    }
}

// ==========================================================================
// TEMPLATES
// ==========================================================================

const TEMPLATES = {
  features: `import React from 'react';
import DocPanel from '../../Components/Common/DocMain/DocPanel';
import CodePreview from '../../Components/Common/CodePreview';
import RichText from '../../Components/Common/RichText';

// Import your custom demos from custom-components
import { 
    BasicDemo,
    BasicSource,
} from './import';

// Define features for {{ComponentName}}
export const {{ComponentName}}FeatureItems = [
    {
        id: "basic",
        sectionNav: "Basic",
        sectionDesc: <RichText as="span" content="The <code>{{ComponentName}}</code> component basic usage." />,
        demo: (
            <CodePreview 
                demo={<BasicDemo />} 
                source={BasicSource} 
                snippetName="basic" 
                language="jsx" 
            />
        ),
    },
];

// Export component for direct use
export default function {{ComponentName}}Features() {
    return (
        <DocPanel 
            Header="{{ComponentName}}" 
            SubHeader="{{ComponentName}} is a ULS component." 
            features={{{ComponentName}}FeatureItems}
        />
    );
}`,

  import: `// ==========================================================================
// {{ComponentName}} Demo Components Barrel Export
// ==========================================================================
// Imports demo components from custom-components folder

export { default as BasicDemo } from '../../custom-components/{{ComponentName}}/BasicDemo';
export { default as BasicSource } from '../../custom-components/{{ComponentName}}/BasicDemo/BasicDemo.jsx?raw';
`,

  meta: `// ==========================================================================
// {{ComponentName}} COMPONENT METADATA
// ==========================================================================

export default {
  category: '{{Category}}',
  subCategory: '{{SubCategory}}',
  menuItem: '{{ComponentName}}',
  routeBase: '/{{routeBase}}',
  icon: 'pi pi-box',
  header: '{{ComponentName}}',
  subHeader: '{{ComponentName}} component from @uls/components',
  tabs: [
    {
      name: 'Features',
      route: '/features',
      component: () => import('./features.jsx')
    }
  ],
  importMsg: "import { {{ComponentName}} } from '@uls/components'"
};
`,

  index: `import React from 'react';
import DocPageWrapper from '../../Components/Common/DocMain/DocPageWrapper';

export default function {{ComponentName}}Page() {
  return <DocPageWrapper componentName="{{componentName}}" />;
}`,

  demoComponent: `import React from 'react';
import { {{ComponentName}} } from '@uls/components';

export default function BasicDemo() {
    return (
        <div className="p-4">
            <{{ComponentName}} variant="primary" size="medium">
                {{ComponentName}} Content
            </{{ComponentName}}>
        </div>
    );
}
`,

  demoIndex: `export { default } from './BasicDemo';
`
};

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function replaceTemplateVariables(template, variables) {
    let result = template;
    Object.entries(variables).forEach(([key, value]) => {
        const regex = new RegExp(`{{${key}}}`, 'g');
        result = result.replace(regex, value || '');
    });
    return result;
}

function generateComponentVariations(componentName) {
    const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1).replace(/-([a-z])/g, (g) => g[1].toUpperCase());
    const kebabCase = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
    const camelCase = pascalCase.charAt(0).toLowerCase() + pascalCase.slice(1);
    
    return {
        ComponentName: pascalCase,
        componentName: camelCase,
        kebabName: kebabCase,
        routeBase: kebabCase
    };
}

function findULSPackage() {
    // Try to find ULS package
    let currentDir = __dirname;
    
    // Go up to find uls-primereact (scripts/ -> root)
    while (currentDir !== path.dirname(currentDir)) {
        const primereactPath = path.join(currentDir, 'libs', 'uls-primereact');
        const ulsComponentsPath = path.join(currentDir, 'uls-components');
        if (fs.existsSync(primereactPath) && fs.existsSync(ulsComponentsPath)) {
            return currentDir; // Return root directory
        }
        currentDir = path.dirname(currentDir);
    }
    
    return null;
}

function validateULSComponentExists(componentName) {
    const ulsRoot = findULSPackage();
    if (!ulsRoot) {
        throw new Error('ULS package not found. Make sure you are running from ULS workspace.');
    }
    
    // Convert ComponentName to kebab-case
    const kebabName = componentName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
    
    // Only check in official components folder (this script is for official ULS components only)
    const componentPath = path.join(ulsRoot, 'uls-components', 'src', 'components', kebabName);
    const componentIndexPath = path.join(componentPath, 'index.js');
    const componentFile = path.join(componentPath, `${kebabName}.jsx`);
    
    // Check if component exists in official components
    if (fs.existsSync(componentIndexPath) || fs.existsSync(componentFile)) {
        return true;
    }
    
    // Component not found
    throw new Error(
        `ULS official component "${componentName}" not found.\n` +
        `Checked:\n` +
        `  - ${componentIndexPath}\n` +
        `  - ${componentFile}\n` +
        `Make sure the component exists in uls-components/src/components/\n` +
        `For custom-components, use: npm run create-custom-component-demo ${componentName}`
    );
}

function getExistingCategories(uiComponentsPath) {
    const categories = new Set();
    const subCategories = new Set();
    
    if (!fs.existsSync(uiComponentsPath)) {
        return { categories: [], subCategories: [] };
    }
    
    try {
        const componentFolders = fs.readdirSync(uiComponentsPath, { withFileTypes: true })
            .filter(dirent => dirent.isDirectory() && dirent.name.endsWith('Page'));
        
        for (const folder of componentFolders) {
            const metaPath = path.join(uiComponentsPath, folder.name, 'meta.js');
            if (fs.existsSync(metaPath)) {
                try {
                    // Read and parse meta.js (simple regex extraction, not full parsing)
                    const content = fs.readFileSync(metaPath, 'utf8');
                    const categoryMatch = content.match(/category:\s*['"]([^'"]+)['"]/);
                    const subCategoryMatch = content.match(/subCategory:\s*['"]([^'"]+)['"]/);
                    
                    if (categoryMatch) {
                        categories.add(categoryMatch[1]);
                    }
                    if (subCategoryMatch) {
                        subCategories.add(subCategoryMatch[1]);
                    }
                } catch (err) {
                    // Skip if can't parse
                }
            }
        }
    } catch (err) {
        // Return empty if can't read directory
    }
    
    return {
        categories: Array.from(categories).sort(),
        subCategories: Array.from(subCategories).sort()
    };
}

// ==========================================================================
// MAIN GENERATOR FUNCTION
// ==========================================================================

async function createULSComponentDemo() {
    try {
        // Parse command line args
        const args = process.argv.slice(2);
        let componentName = args[0];
        
        if (!componentName) {
            console.error('❌ Error: Component name is required');
            console.log('\nUsage:');
            console.log('  npm run create-uls-component-demo <ComponentName>');
            console.log('  node scripts/create-uls-component-demo.mjs <ComponentName>');
            console.log('\nExamples:');
            console.log('  npm run create-uls-component-demo UserCard');
            console.log('  npm run create-uls-component-demo NewFeature');
            process.exit(1);
        }
        
        // Validate component exists
        validateULSComponentExists(componentName);
        
        const variations = generateComponentVariations(componentName);
        const pageFolderName = `${variations.ComponentName}Page`;
        
        // Find uls-primereact directory
        const ulsPackage = findULSPackage();
        if (!ulsPackage) {
            throw new Error('ULS package not found. Make sure you are running from ULS workspace.');
        }
        
        const primereactPath = path.join(ulsPackage, 'src/libs/uls-primereact');
        if (!fs.existsSync(primereactPath)) {
            throw new Error(`uls-primereact not found at: ${primereactPath}`);
        }
        
        // Get existing categories for suggestions
        const uiComponentsPath = path.join(primereactPath, 'src/Pages/Documentation/UiComponents');
        const existingCategories = getExistingCategories(uiComponentsPath);
        
        // Prompt for category and subCategory
        let category = 'ULS Components';
        let subCategory = 'Components';
        
        // Show existing categories if available
        if (existingCategories.categories.length > 0) {
            console.log('\n📋 Existing categories:', existingCategories.categories.join(', '));
        }
        if (existingCategories.subCategories.length > 0) {
            console.log('📋 Existing sub-categories:', existingCategories.subCategories.join(', '));
        }
        
        const inquirerModule = await getInquirer();
        if (inquirerModule) {
            const answers = await inquirerModule.prompt([
                {
                    type: 'input',
                    name: 'category',
                    message: 'Category:',
                    default: 'ULS Components',
                    validate: (input) => input.trim().length > 0 || 'Category is required'
                },
                {
                    type: 'input',
                    name: 'subCategory',
                    message: 'Sub Category:',
                    default: 'Components',
                    validate: (input) => input.trim().length > 0 || 'Sub Category is required'
                }
            ]);
            category = answers.category.trim();
            subCategory = answers.subCategory.trim();
            console.log(`\n✅ Selected category: "${category}"`);
            console.log(`✅ Selected sub-category: "${subCategory}"\n`);
        } else {
            // Fallback: use readline prompts
            console.log('\n💡 Using readline prompts (inquirer not available)');
            const answers = await promptUsingReadline('ULS Components', 'Components');
            category = answers.category || 'ULS Components';
            subCategory = answers.subCategory || 'Components';
            category = category.trim();
            subCategory = subCategory.trim();
            console.log(`\n✅ Selected category: "${category}"`);
            console.log(`✅ Selected sub-category: "${subCategory}"\n`);
        }
        
        // Create paths
        const customDemoPath = path.join(primereactPath, 'src/custom-demo');
        const demoPagePath = path.join(customDemoPath, pageFolderName);
        const customComponentsPath = path.join(primereactPath, 'src/custom-components');
        const componentFolderPath = path.join(customComponentsPath, variations.ComponentName);
        const demoComponentPath = path.join(componentFolderPath, 'BasicDemo');
        const demoFilePath = path.join(demoComponentPath, 'BasicDemo.jsx');
        
        // Check if already exists
        if (fs.existsSync(demoPagePath)) {
            console.warn(`⚠️  Demo page "${pageFolderName}" already exists at: ${demoPagePath}`);
            console.log('   Skipping creation. Use create-custom-demo-type to add more demos.');
            process.exit(0);
        }
        
        // Create directories
        fs.mkdirSync(demoPagePath, { recursive: true });
        fs.mkdirSync(componentFolderPath, { recursive: true });
        fs.mkdirSync(demoComponentPath, { recursive: true });
        console.log(`📁 Created directory: ${path.relative(process.cwd(), demoPagePath)}`);
        console.log(`📁 Created directory: ${path.relative(process.cwd(), componentFolderPath)}`);
        console.log(`📁 Created directory: ${path.relative(process.cwd(), demoComponentPath)}`);
        
        // Template variables
        const templateVars = {
            ...variations,
            Category: category,
            SubCategory: subCategory
        };
        
        // Generate files
        const files = [
            {
                path: path.join(demoPagePath, 'features.jsx'),
                content: replaceTemplateVariables(TEMPLATES.features, templateVars)
            },
            {
                path: path.join(demoPagePath, 'import.js'),
                content: replaceTemplateVariables(TEMPLATES.import, templateVars)
            },
            {
                path: path.join(demoPagePath, 'meta.js'),
                content: replaceTemplateVariables(TEMPLATES.meta, templateVars)
            },
            {
                path: path.join(demoPagePath, 'index.jsx'),
                content: replaceTemplateVariables(TEMPLATES.index, templateVars)
            },
            {
                path: demoFilePath,
                content: replaceTemplateVariables(TEMPLATES.demoComponent, templateVars)
            },
            {
                path: path.join(demoComponentPath, 'index.jsx'),
                content: replaceTemplateVariables(TEMPLATES.demoIndex, templateVars)
            }
        ];
        
        // Write files
        files.forEach(({ path: filePath, content }) => {
            fs.writeFileSync(filePath, content, 'utf8');
            console.log(`📝 Created: ${path.relative(process.cwd(), filePath)}`);
        });
        
        console.log(`\n🎉 Successfully created demo page for ${variations.ComponentName}!`);
        console.log(`\n📦 Files created:`);
        console.log(`   Demo page: ${demoPagePath}`);
        console.log(`   Demo component: ${demoFilePath}`);
        
        // Automatically register the component in navigation
        console.log(`\n📦 Registering ${variations.ComponentName} in main navigation...`);
        try {
            // Dynamically import the registration function
            const { registerComponentDemo } = await import('./register-uls-component-demo.mjs');
            await registerComponentDemo(componentName, { skipIfExists: true });
            console.log(`\n✅ Component registered and ready!`);
        } catch (regError) {
            console.warn(`\n⚠️  Warning: Could not auto-register component: ${regError.message}`);
            console.log(`   You can register it manually using: npm run register-uls-component-demo ${componentName}`);
        }
        
        console.log(`\n💡 Next steps:`);
        console.log(`   1. Customize the demo in: ${demoFilePath}`);
        console.log(`   2. Add more demos using: npm run uls create-custom-demo-type Basic --component=${variations.ComponentName}`);
        console.log(`   3. The component is now available in the demo app navigation!`);
        
    } catch (error) {
        console.error('\n❌ Error:', error.message);
        if (error.stack) {
            console.error('\nStack trace:', error.stack);
        }
        process.exit(1);
    }
}

// Run the generator
createULSComponentDemo();

